const crypto = require('node:crypto')
const { createXYSeriesReceiver } = require('./xy-series-frame')
const { readJsonBody, replyJson } = require('./panel-http')
const { xySeriesRoute } = require('./xy-series-route')
const { emitTelemetryFrame } = require('./panel-telemetry-send')
const { createTelemetryScheduler } = require('./panel-telemetry-scheduler')

function createXYSeriesRoom ({ room, now = Date.now, staleMs = 1000 }) {
  const sources = new Map(), panels = new Map()
  const scheduler = createTelemetryScheduler()
  let generation = 0

  function attach (panelId, bindings) {
    if (panels.has(panelId)) throw Error('XY-series panel already registered')
    const entries = Object.entries(bindings).filter(([, entry]) => entry.readMeta?.xySeries)
      .sort(([a], [b]) => a.localeCompare(b))
    if (!entries.length || entries.length > 256) throw Error('Invalid xy-series panel size')
    // Validate the whole registration before changing shared sources or references.
    const proposed = new Map()
    for (const [, binding] of entries) {
      const series = xySeriesRoute(binding.readMeta.xySeries)
      const key = JSON.stringify([binding.device, series.streamId])
      const previous = sources.get(key)?.route || proposed.get(key)
      if (previous && JSON.stringify(previous) !== JSON.stringify(series)) {
        throw Error(`Conflicting xy-series stream: ${series.streamId}`)
      }
      proposed.set(key, series)
    }
    const projections = entries.map(([id, binding]) => {
      const series = xySeriesRoute(binding.readMeta.xySeries)
      const key = JSON.stringify([binding.device, series.streamId])
      let source = sources.get(key)
      if (!source) {
        source = { device: binding.device, route: series, receiver: null,
          receivedAt: null, revision: 0, refs: new Set() }
        sources.set(key, source)
      }
      source.refs.add(panelId)
      return { id, binding, source, key }
    })
    const layout = { kind: 'room-xy-series-layout', panelId, room,
      epoch: crypto.randomBytes(16).toString('hex'), ids: entries.map(([id]) => id) }
    panels.set(panelId, { projections, streams: [...new Set(projections.map(point => point.source))], layout, sequence: 0 })
    return layout
  }

  function accept (message) {
    if (!['device-xy-series-frame', 'device-xy-series-manifest'].includes(message?.kind)) return false
    const source = sources.get(JSON.stringify([message.device, message.streamId]))
    if (!source || message.path !== (message.kind === 'device-xy-series-frame'
      ? source.route.eventPath : source.route.manifestPath)) return false
    let data = message.payload
    if (data && typeof data === 'object' && Object.hasOwn(data, 'data')) data = data.data
    if (typeof data === 'string') {
      if (Buffer.byteLength(data) > 524288) return false
      try { data = JSON.parse(data) } catch (_) { return false }
    }
    if (message.kind === 'device-xy-series-manifest') {
      let receiver
      try { receiver = createXYSeriesReceiver(data) } catch (_) { return false }
      if (receiver.manifest.streamId !== source.route.streamId) return false
      const previous = source.receiver?.manifest
      if (previous && JSON.stringify(previous) === JSON.stringify(receiver.manifest)) return true
      if (previous?.epoch === receiver.manifest.epoch &&
        receiver.manifest.layoutVersion <= previous.layoutVersion) return false
      source.receiver?.close(); source.receiver = receiver; source.receivedAt = null
    } else {
      if (!source.receiver?.accept(data)) return false
      source.receivedAt = now()
    }
    source.revision = ++generation
    return true
  }

  function snapshot (panelId, { copyPoints = true } = {}) {
    const panel = panels.get(panelId)
    if (!panel) return null
    const time = now(), values = [], valid = [], sourcesByStream = new Map()
    for (const { source, key } of panel.projections) {
      const frame = source.receiver?.snapshot()
      const age = source.receivedAt === null ? null : Math.max(0, time - source.receivedAt)
      const ok = Boolean(frame && age !== null && age <= staleMs)
      // The transport only serializes these deeply frozen points. Public
      // snapshots still copy, so callers and alias bindings remain independent.
      values.push(ok ? (copyPoints ? frame.points.map(point => [point[0], point[1]]) : frame.points) : [])
      valid.push(ok)
      sourcesByStream.set(key, { device: source.device, streamId: source.route.streamId,
        epoch: source.receiver?.manifest.epoch || '', seq: frame?.seq || 0,
        sampleTime: frame?.sampleTime ?? null, ageMs: age })
    }
    return { kind: 'room-xy-series-frame', panelId, room, epoch: panel.layout.epoch,
      seq: ++panel.sequence, values, valid, sources: [...sourcesByStream.values()] }
  }

  function revision (panelId) {
    const panel = panels.get(panelId)
    if (!panel) return ''
    const time = now()
    return panel.streams.map(source => `${source.revision}:${source.receivedAt !== null &&
      time - source.receivedAt <= staleMs}`).join(',')
  }

  function detach (panelId) {
    const panel = panels.get(panelId)
    if (!panel) return
    panels.delete(panelId)
    for (const { source, key } of panel.projections) {
      source.refs.delete(panelId)
      if (!source.refs.size) { source.receiver?.close(); sources.delete(key) }
    }
  }

  return { attach, accept, snapshot, revision, detach,
    onTick: callback => scheduler.onTick(callback),
    stats: () => ({ panels: panels.size, sources: sources.size }) }
}

function createPanelXYSeries ({ panelId, room, bindings, hub, onSubscribe = () => {} }) {
  const layout = hub.attach(panelId, bindings)
  const tickets = new Map(), subscribers = new Map()
  let closed = false, lastRevision = ''
  const remove = socketId => {
    const entry = subscribers.get(socketId)
    if (entry) entry.socket.off('disconnect', entry.disconnect)
    subscribers.delete(socketId)
  }
  const live = entry => entry.active() && entry.socket.connected
  const emitFrame = (socket, frame) => socket.volatile.emit('control-panel:xy-series-frame', frame)
  const prune = () => {
    for (const [key, entry] of tickets) if (entry.expiry <= Date.now() || !entry.active()) tickets.delete(key)
    for (const [key, entry] of subscribers) if (!live(entry)) {
      entry.socket.emit('control-panel:xy-series-ended', { panelId }); remove(key)
    }
  }
  const stopTick = hub.onTick(() => {
    prune()
    if (closed || !subscribers.size) return
    const revision = hub.revision(panelId)
    if (revision === lastRevision) return
    lastRevision = revision
    const frame = hub.snapshot(panelId, { copyPoints: false })
    emitTelemetryFrame('control-panel:xy-series-frame', frame, subscribers)
  })
  return {
    async ticket (req, res, identity, active) {
      if (!new URL(req.url, 'http://localhost').pathname.endsWith('/xy-series-ticket') || req.method !== 'POST') return false
      if (closed) { replyJson(res, 503, { error: 'XY-series channel unavailable' }); return true }
      prune()
      const body = await readJsonBody(req, 4096)
      if (body.room !== room || typeof body.socketId !== 'string' || !body.socketId || body.socketId.length > 128) {
        replyJson(res, 403, { error: 'XY-series subscription rejected' }); return true
      }
      if (!req.headers.origin) { replyJson(res, 403, { error: 'XY-series subscription needs Origin' }); return true }
      for (const [key, entry] of tickets) if (entry.token === identity.token && entry.socketId === body.socketId) tickets.delete(key)
      if (tickets.size >= 100) { replyJson(res, 429, { error: 'XY-series ticket limit reached' }); return true }
      const ticket = crypto.randomBytes(32).toString('hex')
      tickets.set(ticket, { token: identity.token, socketId: body.socketId,
        expiry: Math.min(identity.expiry, Date.now() + 10000), active })
      replyJson(res, 200, { ticket }); return true
    },
    hooks: {
      'control-panel:xy-series-subscribe': (socket, id, ticket) => {
        if (id !== panelId || closed) return
        prune()
        const entry = tickets.get(ticket); tickets.delete(ticket)
        if (!entry || !entry.active() || entry.expiry <= Date.now() || entry.socketId !== socket.id ||
          !socket.connected || (!subscribers.has(socket.id) && subscribers.size >= 100)) {
          socket.emit('control-panel:xy-series-ended', { panelId }); return
        }
        remove(socket.id)
        const disconnect = () => remove(socket.id)
        subscribers.set(socket.id, { socket, active: entry.active, disconnect })
        socket.on('disconnect', disconnect)
        socket.emit('control-panel:xy-series-ready', { ...layout, subscriptionId: ticket })
        emitFrame(socket, hub.snapshot(panelId)); onSubscribe()
      },
      'control-panel:xy-series-unsubscribe': (socket, id) => { if (id === panelId) remove(socket.id) }
    },
    accept: message => !closed && hub.accept(message),
    stats: () => ({ tickets: tickets.size, subscribers: subscribers.size, ...hub.stats() }),
    close () {
      closed = true; stopTick(); tickets.clear()
      for (const entry of subscribers.values()) {
        entry.socket.emit('control-panel:xy-series-ended', { panelId })
        entry.socket.off('disconnect', entry.disconnect)
      }
      subscribers.clear(); hub.detach(panelId)
    }
  }
}

module.exports = { createXYSeriesRoom, createPanelXYSeries }
